FICHES.append(fiche(
 id='decheance-nationalite-binationaux', affirmation="Il faut déchoir de leur nationalité les binationaux qui commettent des crimes.", volet='immigration', sous_theme='Nationalité et accès aux droits',
 mots_cles=['decheance de nationalite', 'dechoir binationaux', 'binationaux criminels', 'retirer nationalite', 'decheance nationalite terroristes', 'article 25 code civil', 'double nationalite crimes', 'perdre nationalite francaise'],
 verdict='opinion', fiabilite='debattu',
 resume="C'est un choix politique, mais il repose souvent sur une méconnaissance du droit. La déchéance existe déjà (article 25 du code civil) : elle ne vise que des personnes devenues françaises, condamnées pour terrorisme ou atteinte grave à la Nation, et ne peut jamais rendre apatride. Elle reste rare : quatorze déchéances en quatre ans selon le ministère en 2023. L'étendre à tous les binationaux délinquants créerait deux catégories de Français pour un même délit, ce que la réforme de 2015-2016 n'a pas réussi à imposer et ce que le Conseil constitutionnel encadre strictement.",
 contexte="Après les attentats de 2015, François Hollande a voulu inscrire dans la Constitution la déchéance des terroristes binationaux, avant d'y renoncer en mars 2016. L'idée revient régulièrement, étendue aux délinquants.",
 explication="Il faut distinguer ce que permet déjà la loi, son usage réel, les limites posées par les juges (égalité, interdiction de l'apatridie) et le choix politique d'aller plus loin.",
 sources=[NA_AN_QE162_2023, NA_CC_2015, NA_CE_2016, NA_ELYSEE_2016, NA_ACTEURSPUBLICS_2016, NA_PS_CC_2024],
 faits=[
  fait("L'article 25 du code civil ne permet de déchoir que des personnes ayant acquis la nationalité française, sans les rendre apatrides, pour terrorisme, atteinte aux intérêts fondamentaux de la Nation et quelques autres cas, avec l'avis conforme du Conseil d'État.", 'na_an_qe162_2023', '2023', 'France', "La déchéance existe déjà, mais elle est encadrée et ne vise pas la délinquance ordinaire.", 'etabli'),
  fait("Selon le ministère de l'Intérieur, quatorze déchéances visant des personnes condamnées pour terrorisme ont été prononcées en quatre ans, dont six en 2022, un record annuel.", 'na_an_qe162_2023', '2019-2022', 'France', "Fait défavorable : l'État utilise de plus en plus cet outil contre le terrorisme.", 'etabli', '14 déchéances'),
  fait("Le Conseil constitutionnel juge que Français de naissance et Français par acquisition sont « dans la même situation », et n'admet une différence, limitée dans le temps, que pour la lutte contre le terrorisme ; depuis 1998, la déchéance ne peut rendre apatride.", 'na_cc_2015', '2015', 'France', "L'égalité entre Français limite strictement la déchéance.", 'etabli'),
  fait("Avant 2015, la déchéance était exceptionnelle : moins de dix cas sur la décennie selon le rapport Mariani de 2010, aucune entre 2007 et 2011.", 'na_cc_2015', '2000-2014', 'France', "Une mesure symbolique, très peu utilisée.", 'etabli', 'moins de dix cas'),
  fait("En 2016, le Conseil d'État a validé cinq déchéances prononcées en 2015 contre des personnes condamnées pour terrorisme, jugées non disproportionnées.", 'na_ce_2016', '2015-2016', 'France', "Fait défavorable : l'outil existe et les juges l'appliquent pour les faits les plus graves.", 'etabli', '5 déchéances'),
  fait("Le 30 mars 2016, François Hollande a abandonné la révision constitutionnelle, faute d'accord entre l'Assemblée et le Sénat sur la déchéance ; le débat avait entraîné la démission de la garde des Sceaux Christiane Taubira. En 2024, l'extension de la déchéance au meurtre d'une personne dépositaire de l'autorité publique a été censurée.", 'na_elysee_2016', '2016', 'France', "Chaque tentative d'extension a échoué.", 'etabli'),
 ],
 court="La déchéance existe déjà pour les terroristes devenus français, et elle reste rare : quatorze en quatre ans. L'étendre aux délinquants binationaux ferait deux catégories de Français pour un même délit. Le Conseil constitutionnel rappelle que tous les Français sont « dans la même situation ».",
 moyen="Le droit permet déjà de déchoir de leur nationalité des personnes devenues françaises et condamnées pour terrorisme ou atteinte grave à la Nation, à condition qu'elles aient une autre nationalité : on ne peut rendre personne apatride. Selon le ministère, quatorze déchéances ont été prononcées en quatre ans, dont six en 2022.\n\nL'étendre à tous les binationaux délinquants, c'est punir plus durement un Français parce qu'il a une autre nationalité. Le Conseil constitutionnel n'admet cette différence que pour le terrorisme. En 2016, la réforme voulue après les attentats a été abandonnée, et en 2024 une extension a été censurée.",
 detaille="La déchéance de nationalité existe déjà. L'article 25 du code civil permet de retirer la nationalité à une personne qui l'a acquise, si elle a une autre nationalité, en cas de condamnation pour terrorisme, atteinte aux intérêts fondamentaux de la Nation et quelques autres cas. Elle ne peut jamais rendre apatride et passe par l'avis conforme du Conseil d'État. Longtemps rarissime (moins de dix cas en dix ans selon un rapport de 2010), elle est davantage utilisée depuis 2015 : quatorze déchéances en quatre ans, dont six en 2022, selon le ministère de l'Intérieur. En 2016, le Conseil d'État a validé cinq déchéances de condamnés pour terrorisme.\n\nAller plus loin pose une question de principe. Le Conseil constitutionnel juge que Français de naissance et Français par acquisition sont « dans la même situation », et ne tolère une différence que pour le terrorisme, pendant une durée limitée. Viser tous les binationaux délinquants, ce serait dire à des Français que leur citoyenneté est conditionnelle, et punir deux fois plus lourdement un même délit selon l'origine de ses parents.\n\nC'est pourquoi la réforme lancée après les attentats de 2015 a échoué : le 30 mars 2016, François Hollande a renoncé, faute d'accord entre l'Assemblée et le Sénat, après un débat qui avait provoqué la démission de Christiane Taubira. En 2024, l'extension au meurtre d'un dépositaire de l'autorité publique a été censurée. Contre la délinquance, la réponse est la justice pénale, la même pour tous les Français.",
 empathie="On peut vouloir que ceux qui trahissent le pays ou frappent ses habitants en subissent les conséquences. Ce désir de justice est légitime ; la question est de savoir si l'on punit des actes ou des origines.",
 legitimes=["La déchéance des personnes condamnées pour terrorisme existe en droit et a été validée par les juges.", "Il est légitime de débattre des conséquences des crimes les plus graves contre la Nation."],
 contre=[
  ("Ils n'avaient qu'à respecter la France.", "La loi punit déjà les délits par la prison ; retirer la nationalité aux seuls binationaux frapperait différemment deux Français pour le même acte."),
  ("La gauche elle-même voulait la déchéance en 2015.", "Oui, et ce projet a déchiré la gauche, provoqué la démission de la garde des Sceaux et été abandonné en 2016 faute d'accord."),
 ],
 questions=["Trouverais-tu juste que deux Français condamnés pour le même délit soient punis différemment selon la nationalité de leurs parents ?", "Savais-tu que la France ne peut pas déchoir quelqu'un qui n'a pas d'autre nationalité ?"],
 limites=["Le nombre de déchéances après 2022 n'a pas été trouvé dans une source lue.", "Aucune source lue n'évalue l'effet dissuasif ou sécuritaire de la déchéance.", "Le motif exact de la censure de 2024 (fond ou procédure) n'est pas précisé dans la source lue.", "L'article 25 du code civil n'a pas été lu sur Légifrance ; son contenu provient de la réponse ministérielle de 2023 et du Conseil d'État."],
 publics={'convaincus': "La déchéance existe déjà pour les terroristes devenus français : quatorze en quatre ans. Mais l'étendre aux délinquants binationaux, c'est punir plus lourdement un Français pour la même faute, selon ses origines. Et on ne peut déchoir personne sans autre nationalité : un délinquant « 100 % français » ne serait jamais concerné.",
  'indecis': "Vouloir sanctionner sévèrement les crimes graves est compréhensible, et la loi le permet déjà pour le terrorisme. Mais aller plus loin créerait deux catégories de Français. Même Hollande a dû abandonner sa réforme en 2016 ; le Conseil constitutionnel rappelle que tous les Français sont dans la même situation."},
 a_actualiser='2027-06-30', raison="Nouvelles propositions de loi sur la nationalité et chiffres récents des déchéances.",
))

