FICHES.append(fiche(
 id='attaques-couteau-ensauvagement', affirmation="Il y a des attaques au couteau tous les jours, c'est l'ensauvagement.", volet='securite', sous_theme='Violences',
 mots_cles=['attaques au couteau', 'ensauvagement', '120 attaques par jour', 'agressions arme blanche', 'coups de couteau', 'violence explose', 'france ensauvagee', 'couteau tous les jours'],
 verdict='trompeur', fiabilite='estimation',
 resume="Des agressions au couteau ont lieu chaque jour en France, c'est vrai, et les violences physiques enregistrées augmentent. Mais le chiffre de « 120 attaques par jour » est une estimation ancienne tirée d'une enquête auprès des victimes (2015-2017), pas un comptage. Les homicides ont fortement baissé depuis 1990 et restent rares (982 en 2025). Le mot « ensauvagement », venu de l'extrême droite, transforme une réalité à traiter en panique morale.",
 contexte="Le chiffre de « 120 agressions au couteau par jour » circule depuis 2020 dans des questions parlementaires et sur les réseaux sociaux ; le mot « ensauvagement » a été repris la même année par le ministre de l'Intérieur.",
 explication="Il faut distinguer une estimation par enquête de victimation, les faits enregistrés par la police, les condamnations et les homicides. Il faut aussi comparer dans le temps, au lieu de juger sur des vidéos.",
 sources=[NB_AN_QE27292_2020, NB_SENAT_QE_2022, NB_ONDRP_FLASH30_2020, NB_CESDIP_HOMICIDE, NB_EUROPE1_ENSAUVAGEMENT_2020, NB_LALIBRE_2020, NB_CONNEXION_2026],
 faits=[
  fait("Le chiffre de 120 victimes par jour vient d'une estimation de l'ONDRP : 44 000 victimes d'agressions à l'arme blanche en moyenne entre 2015 et 2017, soit 37 % des 118 000 personnes déclarant chaque année des violences physiques hors ménage.", 'nb_senat_qe_2022', '2015-2017', 'France', "C'est une estimation par enquête auprès des victimes, déjà ancienne, pas un comptage d'attaques.", 'estimation', '44 000 victimes'),
  fait("Le ministère de la Justice a répondu en 2020 que ce chiffre « ne résulte pas de faits constatés par un service de police ou de gendarmerie » ; il comptait 11 000 à 12 000 condamnations par an pour des infractions commises avec une arme, stables depuis une décennie.", 'nb_an_qe27292_2020', '2010-2020', 'France', "Les condamnations pour infractions avec arme ne montrent pas d'explosion.", 'etabli', '11 000 à 12 000 condamnations'),
  fait("Selon l'enquête de victimation analysée par l'ONDRP, 18 % des violences physiques dans l'espace public sont commises avec une arme, dont 7 % avec une arme blanche.", 'nb_ondrp_flash30_2020', '2014-2018', 'France métropolitaine', "La grande majorité des violences de rue se font sans arme.", 'estimation', '7 %'),
  fait("Le taux d'homicides a baissé depuis 1990 ; en 2020, il se situait entre 0,6 et 1,3 pour 100 000 habitants selon la source, avec une légère hausse sur la dernière décennie.", 'nb_cesdip_homicide', '1971-2021', 'France métropolitaine', "Le meurtre reste rare, bien moins fréquent qu'il y a trente ans.", 'etabli', '0,6 à 1,3/100 000'),
  fait("En 2025, 982 homicides ont été enregistrés (+1 %), et les violences physiques ont progressé de 5 %.", 'nb_connexion_2026', '2024-2025', 'France', "Les violences enregistrées augmentent : c'est un fait défavorable à ne pas nier.", 'etabli', '982 homicides'),
  fait("En 2020, les coups et blessures volontaires enregistrés étaient en hausse de 8 % sur un an, une hausse « significative mais pas une explosion » ; le mot « ensauvagement » avait d'abord été employé par l'extrême droite.", 'nb_europe1_ensauvagement_2020', '2019-2020', 'France', "La hausse existe, mais le vocabulaire choisi relève de la peur plus que de la mesure.", 'etabli', '+8 %'),
 ],
 court="Oui, il y a des agressions au couteau, et les violences enregistrées augmentent. Mais les « 120 attaques par jour » sont une estimation ancienne tirée d'une enquête auprès des victimes, pas un comptage. Le meurtre a nettement reculé depuis 1990. Parler d'« ensauvagement », c'est remplacer les chiffres par la peur.",
 moyen="Le chiffre de 120 victimes par jour vient d'une estimation de l'ONDRP pour 2015-2017 : environ 44 000 victimes d'agressions à l'arme blanche par an, d'après les déclarations recueillies dans une enquête. Le ministère de la Justice rappelait en 2020 qu'il ne s'agit pas de faits constatés, et que les condamnations pour infractions avec arme (11 000 à 12 000 par an) étaient stables depuis dix ans.\n\nLes violences physiques enregistrées augmentent, c'est vrai : +5 % en 2025. Mais les homicides ont fortement baissé depuis 1990 et restent rares : 982 en 2025. Le mot « ensauvagement », venu de l'extrême droite, ne mesure rien ; il désigne des coupables au lieu de chercher des causes.",
 detaille="D'où viennent les « 120 attaques au couteau par jour » ? D'une estimation de l'ONDRP, reprise dans des questions parlementaires : 44 000 victimes d'agressions à l'arme blanche par an en moyenne entre 2015 et 2017, soit 37 % des 118 000 personnes déclarant des violences physiques hors ménage. C'est une enquête auprès des victimes, utile mais ancienne, et ce n'est pas un décompte d'attaques. Le ministère de la Justice le rappelait en 2020, en ajoutant que les condamnations pour infractions avec arme, 11 000 à 12 000 par an, étaient stables depuis dix ans.\n\nIl ne faut pas pour autant nier la réalité. Les violences physiques enregistrées augmentent : +8 % en 2020, +5 % en 2025. Le meurtre, lui, a fortement reculé depuis 1990 : le taux d'homicides se situait entre 0,6 et 1,3 pour 100 000 habitants en 2020, et 982 homicides ont été enregistrés en 2025. Selon l'enquête de victimation, 18 % des violences dans l'espace public impliquent une arme, dont 7 % une arme blanche.\n\nLe mot « ensauvagement » a d'abord été employé par l'extrême droite avant d'être repris par un ministre de l'Intérieur en 2020. Le criminologue Christophe Soullez le disait alors : « Aucun chiffre objectif » n'atteste une explosion, et « le choc des images et des vidéos joue sur le ressenti ». Pour faire reculer les violences, il faut des chiffres publics fiables, des policiers de proximité, de la prévention et des moyens pour la justice, pas un mot qui désigne une partie de la population comme « sauvage ».",
 empathie="Les vidéos d'agressions au couteau sont choquantes et la peur d'en être victime est réelle. On peut prendre cette peur au sérieux sans accepter des chiffres déformés.",
 legitimes=["Les violences physiques enregistrées augmentent depuis plusieurs années.", "Les agressions au couteau ne font pas l'objet d'un comptage policier spécifique (seuls les vols avec ce type d'arme le sont, selon une question parlementaire de 2022), ce qui nourrit les rumeurs."],
 contre=[
  ("C'est un chiffre officiel : 120 attaques par jour.", "C'est une estimation par enquête auprès des victimes pour 2015-2017, pas un comptage ; le ministère de la Justice lui-même a rappelé que ce ne sont pas des faits constatés."),
  ("On tue de plus en plus en France.", "Le taux d'homicides a fortement baissé depuis 1990 ; il a légèrement remonté sur la dernière décennie, mais reste loin des niveaux passés."),
 ],
 questions=["Sais-tu d'où vient exactement le chiffre de 120 attaques par jour ?", "Est-ce que tu jugerais la sécurité de ton quartier sur des vidéos ou sur des chiffres sur trente ans ?"],
 limites=["L'estimation de l'ONDRP porte sur 2015-2017 ; aucune estimation plus récente des agressions à l'arme blanche n'a été lue.", "Les pages officielles du ministère de l'Intérieur sur le bilan 2025 n'ont pas pu être ouvertes ; les chiffres 2025 viennent d'un compte rendu de presse.", "Le document du CESDIP sur les homicides n'indique ni auteur ni date.", "La part des homicides commis à l'arme blanche n'est donnée par aucune source lue."],
 publics={'convaincus': "Personne ne nie qu'il y a des agressions au couteau, ni que les violences enregistrées augmentent. Mais le chiffre de 120 par jour est une estimation ancienne tirée d'une enquête, pas un comptage officiel. Et le meurtre a fortement reculé depuis 1990 : il était plus fréquent il y a trente ans.",
  'indecis': "Ta peur est compréhensible : les images tournent en boucle. Les repères fiables existent : le taux d'homicides a baissé depuis 1990, les violences physiques augmentent mais n'explosent pas. Ce qu'il faut, ce sont des chiffres publics et de la prévention, pas un mot qui désigne des coupables."},
 a_actualiser='2027-02-28', raison="Bilan annuel 2026 du service statistique du ministère de l'Intérieur (homicides, violences physiques).",
))

# 2 ── Supprimer les allocations familiales aux parents de délinquants ─────
NB_BDT_CIOTTI_2011 = ('nb_bdt_ciotti_2011', src("Absentéisme scolaire : 160 cas de suspension des allocations familiales, indique le ministère", 'Banque des Territoires (Localtis)', '1er décembre 2011',
  'https://www.banquedesterritoires.fr/absenteisme-scolaire-160-cas-de-suspension-des-allocations-familiales-indique-le-ministere',
  "160 décisions de suspension des allocations familiales depuis l'entrée en vigueur du décret le 24 janvier 2011, dans 27 départements (chiffre confirmé par la CNAF à l'AFP). Le ministre Luc Chatel affirme que 99,5 % des cas ont été résolus « en convoquant les parents ». Eric Ciotti juge sa loi « efficace ».",
  "Média des collectivités locales (Caisse des dépôts) ; appréciations des promoteurs de la loi, sans évaluation indépendante.", 'secondaire'))
NB_BDT_ABROGATION_2013 = ('nb_bdt_abrogation_2013', src("Absentéisme scolaire : la loi Ciotti est définitivement supprimée", 'Banque des Territoires (Localtis)', 'janvier 2013',
  'https://www.banquedesterritoires.fr/absenteisme-scolaire-la-loi-ciotti-est-definitivement-supprimee',
  "Abrogation définitivement adoptée par l'Assemblée nationale le jeudi 17 janvier 2013. 619 allocations familiales suspendues pendant l'année scolaire 2011-2012, dont 142 rétablies après le retour de l'élève. 79 149 signalements d'absentéisme, dont environ 1 % ont abouti à une suspension. La ministre George Pau-Langevin juge le dispositif « inutile » et estime qu'il a échoué pour 80 % des 619 élèves ; Luc Chatel juge ces chiffres « extrêmement partiels ». Le dispositif est remplacé par un accompagnement des parents et un personnel d'éducation référent.",
  "Média des collectivités locales ; chiffres avancés par les deux camps lors du débat parlementaire.", 'secondaire'))
NB_PUBLICSENAT_2023 = ('nb_publicsenat_2023', src("Suppression des allocations familiales : qu'a donné le précédent de l'absentéisme scolaire ?", 'Public Sénat', '7 juillet 2023',
  'https://www.publicsenat.fr/actualites/societe/suppression-des-allocations-familiales-qua-donne-le-precedent-de-labsenteisme-scolaire',
  "Après les émeutes, Emmanuel Macron envisageait de « sanctionner financièrement » les familles et Eric Ciotti appelait à reprendre sa loi de 2010. Entre février 2011 et mars 2012, le dispositif n'a touché que 472 familles. Absentéisme dans le secondaire (DEPP) : 4,3 % en 2009-2010, 5 % en 2010-2011 ; relativement stable autour de 5 % de 2011 à 2015. Le rapporteur de l'abrogation, David Assouline, parlait d'une « réponse répressive univoque, inéquitable et inefficace ». Conclusion de l'article : un précédent « peu probant ».",
  "Chaîne parlementaire du Sénat ; article d'analyse, données DEPP descriptives.", 'secondaire'))
NB_LCP_2023 = ('nb_lcp_2023', src("Suppression des allocations familiales pour les parents d'enfants délinquants : le texte du RN, soutenu par LR, rejeté", 'LCP-Assemblée nationale', '12 octobre 2023',
  'https://lcp.fr/actualites/suppression-des-allocations-familiales-pour-les-parents-d-enfants-delinquants-le-texte',
  "Proposition de loi RN après les violences urbaines de l'été 2023 : suppression de la part des allocations correspondant à l'enfant après une condamnation pour crime, suspension de 24 mois pour un délit puni d'au moins deux ans de prison. Soutenue par LR, rejetée par le gouvernement, la majorité et la gauche ; l'article 1 supprimé, le texte a été retiré. La ministre Aurore Bergé rappelle que la loi permet déjà de suspendre les allocations en cas d'incarcération d'un enfant ; Horizons note que les allocations ne sont dues qu'à partir du deuxième enfant ; le MoDem invoque le principe de responsabilité pénale personnelle.",
  "Chaîne parlementaire de l'Assemblée ; compte rendu des débats.", 'secondaire'))
NB_AN_RAPPORT_2023 = ('nb_an_rapport_2023', src("Rapport n° 1698 sur la proposition de loi visant à supprimer ou à suspendre les allocations familiales pour les parents d'enfants criminels ou délinquants", 'Assemblée nationale, commission des affaires sociales (rapporteur Bryan Masson, RN)', '4 octobre 2023',
  'https://www.assemblee-nationale.fr/dyn/16/rapports/cion-soc/l16b1698_rapport-fond.pdf',
  "Selon le ministère des solidarités, 949 familles ont été concernées par la loi Ciotti ; la courte durée d'application empêche d'évaluer précisément son efficacité, et elle n'a pas réduit l'absentéisme. En cas de placement pénal, les allocations sont versées à la structure qui accueille le mineur. Émeutes de 2023 : 4 481 gardes à vue, dont 1 319 mineurs. Les allocataires sont en général un seul parent, le plus souvent la mère. En décembre 2022 : 4,8 millions de familles bénéficiaires, montant moyen de 222 euros par mois et par famille.",
  "Rapport parlementaire officiel rédigé par l'auteur RN de la proposition : les données (ministères, CNAF) sont utilisées, pas les positions du rapporteur.", 'primaire'))

FICHES.append(fiche(
 id='allocations-familiales-parents-delinquants', affirmation="Il faut supprimer les allocations familiales aux parents des mineurs qui commettent des délits.", volet='securite', sous_theme='Prévention et politiques publiques',
 mots_cles=['allocations familiales parents', 'supprimer les allocs', 'allocs des parents', 'loi ciotti', 'sanctionner les parents', 'allocations emeutiers', 'suspension allocations', 'responsabilite des parents'],
 verdict='opinion', fiabilite='debat',
 resume="C'est un choix politique, mais le précédent existe : la loi Ciotti de 2010 suspendait les allocations en cas d'absentéisme scolaire. Elle a touché quelques centaines de familles, sans effet démontré sur l'absentéisme, et a été abrogée en 2013. Une proposition du RN pour les parents d'enfants délinquants a été rejetée en 2023. La mesure frappe surtout des mères seules et toute la fratrie, sans s'attaquer aux causes de la délinquance.",
 contexte="L'idée revient après chaque flambée de violences urbaines, notamment après les émeutes de l'été 2023, portée par la droite et l'extrême droite, et évoquée par le président de la République.",
 explication="Il faut regarder ce qu'a donné l'expérience de 2010-2013, qui touche réellement la sanction (souvent la mère seule et les autres enfants), et ce que prévoit déjà le droit en cas de placement ou d'incarcération.",
 sources=[NB_BDT_CIOTTI_2011, NB_BDT_ABROGATION_2013, NB_PUBLICSENAT_2023, NB_LCP_2023, NB_AN_RAPPORT_2023],
 faits=[
  fait("La loi Ciotti de 2010 permettait de suspendre les allocations familiales en cas d'absentéisme ; selon les sources, entre 472 familles (février 2011-mars 2012) et 949 familles (bilan du ministère) ont été concernées.", 'nb_publicsenat_2023', '2011-2013', 'France', "La sanction a été très peu appliquée, et ses bilans divergent.", 'estimation', '472 familles'),
  fait("Pendant l'année scolaire 2011-2012, 619 allocations ont été suspendues, dont 142 rétablies après le retour de l'élève ; environ 1 % des 79 149 signalements d'absentéisme ont abouti à une suspension.", 'nb_bdt_abrogation_2013', '2011-2012', 'France', "La mesure a concerné une infime partie des cas.", 'etabli', '619 suspensions'),
  fait("L'absentéisme dans le secondaire est passé de 4,3 % en 2009-2010 à 5 % en 2010-2011, puis est resté autour de 5 % jusqu'en 2015, avant comme après l'abrogation.", 'nb_publicsenat_2023', '2009-2015', 'France', "Aucun effet visible de la sanction sur l'absentéisme.", 'etabli', '5 %'),
  fait("Le ministre de l'époque affirmait que 99,5 % des cas avaient été résolus en convoquant les parents, la menace de suspension servant de levier.", 'nb_bdt_ciotti_2011', '2011', 'France', "Les défenseurs de la loi y voyaient un effet dissuasif ; ce chiffre n'a pas fait l'objet d'une évaluation indépendante (fait défavorable à présenter honnêtement).", 'interpretation', '99,5 %'),
  fait("En 2023, la proposition du RN a été rejetée : le gouvernement rappelait que la loi permet déjà de suspendre les allocations en cas d'incarcération de l'enfant, et des députés soulignaient qu'elles ne sont dues qu'à partir du deuxième enfant.", 'nb_lcp_2023', '2023', 'France', "La mesure serait à la fois redondante et inégale selon la taille des familles.", 'etabli'),
  fait("Après les émeutes de 2023, 4 481 personnes ont été placées en garde à vue, dont 1 319 mineurs ; les allocataires sont en général un seul parent, le plus souvent la mère.", 'nb_an_rapport_2023', '2023', 'France', "La sanction viserait surtout des mères, et priverait aussi les frères et sœurs.", 'etabli', '1 319 mineurs'),
 ],
 court="On a déjà essayé : la loi Ciotti suspendait les allocations en cas d'absentéisme. Quelques centaines de familles touchées, aucun effet visible sur l'absentéisme, abrogée en 2013. Supprimer les allocations, c'est punir une mère et ses autres enfants, pas prévenir la délinquance.",
 moyen="Le précédent existe. De 2011 à 2013, la loi Ciotti permettait de suspendre les allocations familiales des parents d'élèves absentéistes. Elle a touché entre 472 et 949 familles selon les bilans, et l'absentéisme est resté autour de 5 % avant comme après. Elle a été abrogée en 2013.\n\nEn 2023, après les émeutes, le RN a proposé de supprimer les allocations des parents d'enfants délinquants. Le texte a été rejeté : le droit permet déjà de les suspendre en cas d'incarcération, et elles ne sont dues qu'à partir du deuxième enfant. Surtout, l'allocataire est le plus souvent une mère seule : on appauvrirait toute la fratrie, sans s'attaquer aux causes de la délinquance.",
 detaille="Cette idée a déjà été testée. La loi Ciotti de 2010 permettait de suspendre les allocations familiales en cas d'absentéisme scolaire. Selon les bilans, 472 familles (de février 2011 à mars 2012), 619 suspensions sur l'année 2011-2012, ou 949 familles au total ont été concernées. Environ 1 % des 79 149 signalements ont abouti à une suspension. Et l'absentéisme dans le secondaire est resté autour de 5 %, avant comme après. Le ministre de l'époque affirmait que la simple menace réglait 99,5 % des cas, mais aucune évaluation indépendante ne l'a confirmé. La loi a été abrogée en janvier 2013.\n\nAprès les émeutes de 2023, 4 481 personnes ont été placées en garde à vue, dont 1 319 mineurs. Le RN a alors proposé de supprimer les allocations des parents d'enfants condamnés. Le texte a été rejeté. Le gouvernement affirmait que la loi permet déjà de suspendre les allocations en cas d'incarcération ; en cas de placement, elles sont versées à la structure qui accueille l'enfant. Des députés ont souligné qu'une famille d'enfant unique, sans allocations, ne serait pas touchée, et que la responsabilité pénale est personnelle.\n\nLa sanction frapperait surtout des mères seules, puisque l'allocataire est le plus souvent la mère, et elle priverait les frères et sœurs, qui n'ont rien fait. Aucune source lue ne montre qu'appauvrir une famille l'aide à tenir son enfant. La gauche défend d'autres pistes : des éducateurs, des moyens pour la protection de l'enfance, l'accompagnement des parents et des services publics présents dans les quartiers.",
 empathie="Voir des jeunes casser ou agresser met en colère, et on a envie que les parents rendent des comptes. Cette exigence de responsabilité est compréhensible ; la question est de savoir ce qui marche vraiment.",
 legitimes=["Les parents ont un rôle essentiel dans l'éducation de leurs enfants.", "Des parents débordés doivent être repérés et accompagnés plus tôt."],
 contre=[
  ("La menace suffit à faire réagir les parents.", "C'est ce qu'affirmait le ministre de l'époque, mais aucune évaluation indépendante ne l'a montré, et l'absentéisme est resté stable autour de 5 %."),
  ("Pourquoi verser de l'argent public à des familles de délinquants ?", "Les allocations servent à élever tous les enfants du foyer ; en cas de placement, elles vont déjà à la structure qui accueille l'enfant, et l'incarcération permet déjà de les suspendre."),
 ],
 questions=["Si on retire les allocations à une mère seule, qu'arrive-t-il aux petits frères et sœurs ?", "Savais-tu que la loi Ciotti a été appliquée, puis abrogée faute d'effet démontré ?"],
 limites=["Les bilans chiffrés de la loi Ciotti divergent selon les sources (160, 472, 619 ou 949 familles), faute d'évaluation officielle complète.", "Les chiffres d'absentéisme de la DEPP sont descriptifs et ne permettent pas d'isoler l'effet de la loi.", "Aucune sanction de ce type n'a été appliquée en France pour des infractions commises par des enfants : les comparaisons restent indirectes.", "Le rapport parlementaire de 2023 a été lu dans sa première partie seulement ; il relève des informations contradictoires des ministères sur la suspension des allocations en cas d'incarcération."],
 publics={'convaincus': "On a déjà essayé avec la loi Ciotti : quelques centaines de familles sanctionnées, et l'absentéisme est resté autour de 5 %. La loi permet déjà de suspendre les allocations quand un enfant est incarcéré. Retirer l'argent, c'est punir sa mère et ses frères et sœurs, pas l'auteur des faits.",
  'indecis': "Vouloir que les parents assument, c'est légitime. Mais la seule expérience française n'a montré aucun effet, et elle a été abrogée. Plutôt que d'appauvrir des familles, on peut miser sur l'accompagnement des parents et la présence d'éducateurs."},
 a_actualiser='2027-06-30', raison="Nouvelles propositions de loi ou évaluations sur la responsabilité financière des parents.",
))

