FICHES.append(fiche(
 id='musulmans-charia-sondage', affirmation="Les musulmans placent la charia au-dessus des lois de la République.", volet='droits', sous_theme='Laïcité',
 mots_cles=['musulmans charia', 'charia au dessus des lois', 'sondage ifop musulmans', 'loi islamique republique', 'islam et republique', 'musulmans lois francaises', 'institut montaigne charia', 'reislamisation'],
 verdict='trompeur', fiabilite='debat',
 resume="Des sondages montrent une minorité importante sur ce point : 29 % des musulmans jugeaient en 2016 la charia plus importante que la loi de la République, et en 2025, 15 % voulaient l'appliquer intégralement. Mais ce n'est pas « les musulmans » : la majorité ne place pas la religion au-dessus des lois. Les questions sont floues (le sens donné à « charia » n'est pas précisé), et des chercheurs observent des proportions comparables chez d'autres croyants très pratiquants.",
 contexte="Les sondages Ifop pour l'Institut Montaigne (2016) et pour la revue Écran de Veille (2025) ont été très repris dans le débat public, et le second a été vivement contesté par des chercheurs.",
 explication="Il faut lire la question exacte, distinguer pratique religieuse et rejet de la loi commune, et comparer avec les autres croyants.",
 sources=[NB_IFOP_2025, NB_CONVERSATION_2025, NB_MEDIAPART_2025, NB_MONTAIGNE_2016, NB_POLITIS_2016],
 faits=[
  fait("Selon l'Ifop pour l'Institut Montaigne en 2016, 29 % des musulmans interrogés estimaient que la charia est plus importante que la loi de la République.", 'nb_politis_2016', '2016', 'France métropolitaine', "Une minorité significative exprime cette opinion : c'est un fait défavorable à présenter tel quel.", 'estimation', '29 %'),
  fait("En 2025, selon l'Ifop, 15 % des musulmans interrogés veulent que la charia soit appliquée intégralement quel que soit le pays, 31 % en partie en l'adaptant aux règles du pays, et 47 % qu'elle n'ait pas à s'appliquer dans les pays non musulmans.", 'nb_ifop_2025', '2025', 'France métropolitaine', "Le chiffre de 46 % additionne deux réponses très différentes ; le rejet d'une application intégrale est majoritaire.", 'estimation', '15 %'),
  fait("Sur l'abattage rituel, le mariage ou l'héritage, 44 % des musulmans interrogés en 2025 disent qu'ils choisiraient les règles de leur religion, et 49 % les lois françaises, contre 62 % en 1995.", 'nb_ifop_2025', '1995-2025', 'France métropolitaine', "Fait défavorable : l'attachement prioritaire aux lois françaises recule dans ce sondage ; mais ces exemples ne supposent pas forcément d'enfreindre la loi.", 'estimation', '44 %'),
  fait("Pour le sociologue Patrick Simon, choisir les règles religieuses pour l'abattage rituel ou un mariage religieux ne signifie pas une « rupture de la loi commune » ; Vincent Tiberj juge la question sur la charia « pas très sérieux ».", 'nb_conversation_2025', '2025', 'France', "La formulation des questions mélange pratiques religieuses légales et rejet de la loi.", 'interpretation'),
  fait("Le chiffre de 46 % additionne application intégrale et application adaptée ; le mot « charia » n'était pas lu aux répondants, et le groupe de comparaison non musulman ne comptait que 526 personnes.", 'nb_mediapart_2025', '2025', 'France', "La méthodologie du sondage de 2025 fragilise ses conclusions.", 'interpretation'),
  fait("Selon l'enquête publique TeO2 (2019-2020), 41 % des musulmans jugent la religion très importante dans leur vie, contre 14 % des catholiques, à un niveau proche de celui des juifs ; c'était 49 % chez les musulmans en 2008-2009.", 'nb_conversation_2025', '2008-2020', 'France', "Les musulmans sont plus religieux que les catholiques, mais la ferveur n'augmente pas dans la statistique publique.", 'etabli', '41 %'),
 ],
 court="Une minorité de musulmans place la religion avant la loi dans les sondages : 15 % veulent une charia appliquée intégralement selon l'Ifop en 2025. Mais ce n'est pas « les musulmans » : la majorité ne le pense pas, les questions sont floues, et des chercheurs observent des proportions comparables chez d'autres croyants très religieux.",
 moyen="Il ne faut pas cacher les chiffres. En 2016, 29 % des musulmans interrogés par l'Ifop jugeaient la charia plus importante que la loi de la République. En 2025, 15 % voulaient l'appliquer intégralement, et 44 % disaient privilégier les règles religieuses pour l'abattage rituel, le mariage ou l'héritage.\n\nMais lisons les questions. Le « 46 % » de 2025 additionne une application intégrale (15 %) et une application adaptée aux lois du pays (31 %). Choisir un abattage rituel ou un mariage religieux n'est pas violer la loi, souligne le sociologue Patrick Simon. Et selon la statistique publique, 41 % des musulmans jugent la religion très importante, contre 49 % en 2008-2009 : la statistique publique ne montre pas de hausse de la religiosité déclarée.",
 detaille="Les chiffres défavorables existent. En 2016, l'enquête Ifop pour l'Institut Montaigne trouvait que 29 % des musulmans interrogés jugeaient la charia plus importante que la loi de la République ; l'institut décrivait un groupe « autoritaire » de 28 %, majoritairement jeune, inactif et non diplômé. En 2025, un sondage Ifop pour la revue Écran de Veille trouvait 15 % de musulmans favorables à une application intégrale de la charia, et 44 % qui choisiraient les règles de leur religion plutôt que les lois françaises sur l'abattage rituel, le mariage ou l'héritage.\n\nMais ces chiffres disent moins que ce qu'on leur fait dire. Le « 46 % » souvent cité additionne une application intégrale (15 %) et une application « adaptée aux règles du pays » (31 %) ; 47 % répondent qu'elle n'a pas à s'appliquer. Le mot « charia » n'était pas lu aux répondants, et la question ne précise pas de quoi l'on parle. Pour Patrick Simon (Ined), un abattage rituel ou un mariage religieux ne sont pas une « rupture de la loi commune ». Vincent Tiberj juge la question « pas très sérieux » et cite une enquête à Sarcelles où musulmans, chrétiens et juifs placent leurs textes sacrés au-dessus de la République dans des proportions comparables.\n\nLa statistique publique donne un tableau plus calme. Selon l'enquête TeO2 de l'Ined et de l'Insee, 41 % des musulmans jugent la religion très importante dans leur vie, contre 14 % des catholiques et à un niveau proche des juifs, et c'était 49 % en 2008-2009. Il faut prendre au sérieux la minorité qui rejette la loi commune, mais on ne la combat pas en soupçonnant des millions de citoyens : on la combat par l'égalité des droits, l'école laïque et l'application de la même loi à tous.",
 empathie="Ces chiffres de sondage inquiètent, et c'est normal de se demander si nos voisins partagent les mêmes règles. Cette question mérite des réponses précises, pas des généralisations.",
 legitimes=["Une minorité de musulmans interrogés dit placer les règles religieuses avant la loi, et il faut le prendre au sérieux.", "La religiosité est plus forte chez les musulmans que chez les catholiques en France."],
 contre=[
  ("46 % des musulmans veulent la charia en France, c'est l'Ifop qui le dit.", "Ce chiffre additionne 15 % pour une application intégrale et 31 % pour une application adaptée aux lois du pays ; 47 % disent qu'elle n'a pas à s'appliquer."),
  ("Les catholiques, eux, respectent les lois.", "Selon Vincent Tiberj, à Sarcelles, chrétiens, juifs et musulmans placent leurs textes sacrés au-dessus de la République dans des proportions comparables : c'est le fait d'être très croyant, pas l'islam en particulier."),
 ],
 questions=["Si on te demandait si les règles de ta religion comptent plus que la loi, qu'est-ce que tu comprendrais exactement ?", "Est-ce qu'un mariage religieux ou un repas halal, c'est enfreindre la loi ?"],
 limites=["Les sondages sur la charia sont récents mais méthodologiquement contestés ; l'enquête publique TeO2 ne pose pas cette question.", "Le chiffre de 29 % (2016) a été lu dans un article de Politis, le résumé de l'Institut Montaigne ne le donnant pas.", "L'enquête de Sarcelles n'a pas été lue directement : elle est rapportée par Vincent Tiberj.", "La critique de Mediapart a été lue dans une republication militante."],
 publics={'convaincus': "Les sondages montrent bien une minorité qui place la religion avant la loi, je ne le nie pas : 15 % veulent une charia intégrale selon l'Ifop. Mais 47 % disent qu'elle n'a pas à s'appliquer ici, et le fameux « 46 % » additionne des réponses très différentes. Un mariage religieux ou un repas halal, ce n'est pas défier la République.",
  'indecis': "Ces chiffres inquiètent, et ils méritent d'être lus de près. Les questions sont floues, et la statistique publique montre une religiosité stable, voire en léger recul. La meilleure réponse à la minorité qui rejette la loi commune, c'est la même loi pour tous et l'égalité des droits, pas le soupçon sur tous."},
 a_actualiser='2027-06-30', raison="Nouvelles publications de l'enquête TeO2 ou nouveaux sondages sur la religiosité.",
))

