 faits=[
  fait("Le terme « socialiste » a été ajouté au nom du parti en 1920 pour attirer les électeurs ouvriers ; selon Full Fact, le consensus des historiens est que les nazis n'étaient pas socialistes « in any meaningful sense ».", 'nc_fullfact_2019', '1920-1945', 'Allemagne', "Le nom était un outil de propagande.", 'etabli', '1920'),
  fait("Dachau ouvre en mars 1933 ; ses premiers détenus sont surtout des communistes, des sociaux-démocrates et des syndicalistes allemands.", 'nc_ushmm_dachau', '1933', 'Allemagne', "La gauche a été la première cible des nazis.", 'etabli', 'mars 1933'),
  fait("Tous les syndicats sont abolis en mai 1933 et, le 14 juillet 1933, le parti nazi devient le seul parti autorisé.", 'nc_ushmm_gleichschaltung', '1933', 'Allemagne', "Les organisations ouvrières sont détruites.", 'etabli'),
  fait("Lors de la Nuit des longs couteaux (30 juin-2 juillet 1934), une centaine de personnes sont assassinées, dont le chef des SA Ernst Röhm ; l'armée exigeait l'élimination des SA, et Hitler avait besoin du soutien des élites traditionnelles.", 'nc_ushmm_roehm', '1934', 'Allemagne', "Hitler choisit l'armée et les élites contre son aile plébéienne.", 'etabli', 'une centaine'),
  fait("Selon Britannica, le nazisme combinait une idéologie conservatrice et nationaliste avec une « socially radical doctrine » ; une aile se voulait anticapitaliste, mais elle a été éliminée après la prise du pouvoir.", 'nc_britannica_nazism', '1919-1945', 'Allemagne', "Une rhétorique sociale a existé : c'est une limite à reconnaître, mais elle n'a pas survécu à l'exercice du pouvoir.", 'etabli'),
  fait("Au milieu des années 1930, le régime nazi a transféré des entreprises publiques au secteur privé, à rebours des autres grands pays capitalistes, notamment pour obtenir des soutiens politiques.", 'nc_bel_2010', 'années 1930', 'Allemagne', "La politique économique nazie n'était pas une socialisation.", 'etabli'),
 ],
 court="Non. Le mot « socialiste » est dans le nom depuis 1920, mais les historiens s'accordent : les nazis n'étaient pas socialistes. Dès 1933, ils envoient communistes, sociaux-démocrates et syndicalistes à Dachau, abolissent les syndicats et s'appuient sur les conservateurs. Ils privatisent même des entreprises publiques.",
 moyen="Le nom ne fait pas la politique. Le terme « socialiste » a été ajouté en 1920 pour attirer les ouvriers ; l'historien Ian Kershaw résume : « Hitler was never a socialist ». Les premiers détenus de Dachau, en mars 1933, sont des communistes, des sociaux-démocrates et des syndicalistes. En mai 1933, tous les syndicats sont abolis.\n\nHitler arrive au pouvoir avec le soutien de conservateurs. En 1934, il fait assassiner les chefs des SA, qui voulaient remplacer les élites traditionnelles. Et au milieu des années 1930, son régime privatise des entreprises publiques, à contre-courant des autres pays.",
 detaille="Le parti nazi s'appelait « Parti national-socialiste des travailleurs allemands ». Le mot « socialiste » a été ajouté en 1920, pour attirer un électorat ouvrier. Son programme comportait des promesses d'allure anticapitaliste, que l'historien Karl Dietrich Bracher qualifiait de propagande. Selon Full Fact, le consensus des historiens est clair : les nazis n'étaient pas socialistes au sens propre.\n\nLes actes le montrent. Le nazisme se présente comme un rempart contre le communisme. Dès mars 1933, Dachau enferme surtout des communistes, des sociaux-démocrates et des syndicalistes. En mai, tous les syndicats sont abolis ; en juillet, le parti nazi devient parti unique. Hitler a obtenu le soutien de nombreux conservateurs, et il travaillait étroitement avec des industriels qui finançaient le parti.\n\nEn 1934, lors de la Nuit des longs couteaux, il fait tuer une centaine de personnes, dont Ernst Röhm, chef des SA : l'armée exigeait leur élimination et Hitler avait besoin des élites traditionnelles. L'aile qui se disait anticapitaliste disparaît. Sur le plan économique, l'historien Germà Bel montre que le régime a privatisé des entreprises publiques au milieu des années 1930. Classer le nazisme à gauche, c'est ignorer ses ennemis, ses alliés et ses actes.",
 empathie="Le nom du parti peut sembler une preuve évidente, et il est normal de se poser la question. La réponse vient de ce que les nazis ont fait, pas de leur étiquette.",
 legitimes=["Le parti nazi utilisait bien le mot « socialiste » et une rhétorique sociale pour séduire les ouvriers.", "Son programme de 1920 contenait des points d'allure anticapitaliste."],
 contre=[
  ("Ils avaient une économie dirigée par l'État, comme les socialistes.", "Le régime a reprivatisé des entreprises publiques, détruit les syndicats et travaillé avec de grands industriels : l'État dirigeait au service de la guerre, pas des travailleurs."),
  ("Mais le programme du parti était anticapitaliste.", "Certains points pouvaient le sembler, mais l'historien Karl Dietrich Bracher y voit de la propagande, et l'aile qui y croyait a été éliminée en 1934."),
 ],
 questions=["Si les nazis étaient de gauche, pourquoi les premiers détenus de Dachau étaient-ils des communistes et des socialistes ?", "Connais-tu un parti de gauche qui a aboli les syndicats ?"],
 limites=["L'article de Germà Bel n'a été lu qu'à travers ses résumés.", "Aucun fact-check francophone sur cette affirmation n'a pu être ouvert ; les sources sont surtout anglophones.", "L'article de Britannica ne précise pas de date de mise à jour."],
